suppressPackageStartupMessages({library(PharmacoGx);library(data.table);library(MultiAssayExperiment)})
setDTthreads(1)
args <- commandArgs(TRUE); root <- if(length(args)) args[1] else "workflow/scripts"
source(file.path(root,"named_pset_helpers.R")); source(file.path(root,"parse_compound_names.R"))
source("workflow/scripts/construct_observed_tre.R")
raw <- CJ(sampleid=c("5|1","1|4"),treatment1dose=c(1e-8,1e-7,1e-6),tech_rep=c("A","B"))
raw[,`:=`(treatment1id="753082",treatment2id="761431",treatment2dose=1e-6,dose_unit="M",NSC1="753082",NSC2="761431",plateid="p",wellid=as.character(.I),viability=seq_len(.N)/10)]
rkeys <- c("treatment1id","treatment2id","treatment1dose","treatment2dose","dose_unit","NSC1","NSC2")
ckeys <- c("sampleid","tech_rep","plateid","wellid")
t <- construct_observed_tre(raw,rkeys,ckeys,"viability")
sd <- data.frame(sampleid=c("5|1","1|4"),sample_name=c("MCF7","A549/ATCC"),row.names=c("5|1","1|4"))
dd <- data.frame(treatmentid=c("753082","761431"),treatment_name="Vemurafenib",row.names=c("753082","761431"))
se <- SummarizedExperiment(assays=list(rna=matrix(1:6,3,2,dimnames=list(letters[1:3],sd$sampleid))),colData=S4Vectors::DataFrame(sampleid=sd$sampleid,batchid="fixture",row.names=sd$sampleid))
mae <- MultiAssayExperiment(experiments=list(rna=se),colData=S4Vectors::DataFrame(sd))
p <- PharmacoSet2(name="fixture",sample=sd,treatment=dd,molecularProfiles=mae,treatmentResponse=t,curation=list(sample=data.frame(sampleid=sd$sampleid,sampleid_dataset=sd$sampleid,row.names=sd$sampleid),treatment=data.frame(treatmentid=dd$treatmentid,treatmentid_dataset=dd$treatmentid,row.names=dd$treatmentid),tissue=data.frame()),datasetType="sensitivity")
d <- data.frame(nsc=dd$treatmentid,named_treatmentid=paste0("Vemurafenib [NSC ",dd$treatmentid,"]"),preferred_name="Vemurafenib",release_cas=NA_character_,identity_review_flags=NA_character_)
s <- data.frame(source_sampleid=sd$sampleid,named_sampleid=c("MCF-7","A-549"),nci60_2026_sampleid=c("NCI60_MCF7","NCI60_A549_ATCC"))
before <- scientific_fingerprint(p); q <- name_almanac_pset(p,d,s)
stopifnot(identical(before,scientific_fingerprint(q)),identical(p@treatmentResponse@colData$sampleid,t@colData$sampleid),all(grepl("^[0-9]",drugNames(p))),nrow(q@treatment)==2L)
stopifnot(identical(drugNames(q),q@treatment$treatmentid),identical(sampleNames(q),q@sample$sampleid))
sub <- named_pair_response(q,drugNames(q)[1],drugNames(q)[2],samples="MCF-7")
stopifnot(nrow(sub[["raw"]])==6L,all(sub[["raw"]]$sampleid=="MCF-7"))
f <- tempfile(fileext=".rds");saveRDS(q,f);qq<-readRDS(f);stopifnot(identical(scientific_fingerprint(qq),before));unlink(f)
bad <- data.table::copy(d);bad$named_treatmentid[] <- "Vemurafenib"
stopifnot(inherits(try(name_almanac_pset(p,bad,s),silent=TRUE),"try-error"))
bad <- data.table::copy(s);bad$source_sampleid[1]<-"unknown"
stopifnot(inherits(try(name_almanac_pset(p,d,bad),silent=TRUE),"try-error"))
f <- tempfile();writeLines(c("740\tMethotrexate","707389  Eribulin mesylate","737754  Pazopanib hydrochloride","753082  vemurafenib","763371  Ruxolitinib"),f)
parsed <- parse_compound_names(f);stopifnot(nrow(parsed)==5L,parsed[treatmentid=="707389",treatment_name]=="Eribulin mesylate");unlink(f)
cat("PASS: 12 physical observations retained; six named sample/pair records; exact assays/index/molecular values; no source mutation; save/reload; ambiguity and incomplete map rejection; mixed-whitespace parser\n")
legacy <- try(subsetTo(q,drugs=drugNames(q),cells="MCF-7"),silent=TRUE)
cat("Legacy subsetTo compatibility:",if(inherits(legacy,"try-error")) as.character(legacy) else "returned object", "\n")
